    private static HttpResponseMessage CreateErrorResponse(Exception exception)
    {
        string errorCode;
        string errorMessage;
        HttpStatusCode statusCode;

        if (exception is AwsServiceException awsException)
        {
            errorCode = awsException.ErrorCode ?? exception.GetType().Name.Replace("Exception", "");
            errorMessage = awsException.Message;
            statusCode = awsException.StatusCode;
        }
        else
        {
            errorCode = exception.GetType().Name.Replace("Exception", "");
            errorMessage = exception.Message;
            statusCode = HttpStatusCode.InternalServerError;
        }

        var errorType = $"com.amazonaws.events#{errorCode}";

        var errorJson = $$"""
        {
            "__type": "{{errorType}}",
            "message": "{{System.Text.Json.JsonEncodedText.Encode(errorMessage, System.Text.Encodings.Web.JavaScriptEncoder.UnsafeRelaxedJsonEscaping)}}"
        }
        """;

        var response = new HttpResponseMessage(statusCode)
        {
            Content = new StringContent(errorJson, Encoding.UTF8, "application/x-amz-json-1.1")
        };
        return response;
    }
